<?php
require_once 'auth.php'; require_admin(); require_once 'db.php';
$id=strtoupper(trim($_GET['id']??$_POST['original_student_id']??'')); $message=''; $type='error';
if(!valid_student_id($id)){header('Location:view_students.php');exit;}
$st=mysqli_prepare($conn,'SELECT * FROM students WHERE student_id=? LIMIT 1');mysqli_stmt_bind_param($st,'s',$id);mysqli_stmt_execute($st);$student=mysqli_fetch_assoc(mysqli_stmt_get_result($st));if(!$student){header('Location:view_students.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try {

 $index=strtoupper(trim($_POST['index_number']??''));$name=trim($_POST['name']??'');$pin=trim($_POST['pin']??'');$nic=normalize_nic($_POST['nic_number']??'');$active=admin_role()==='data_entry'?(int)$student['is_active']:(isset($_POST['is_active'])?1:0);
 if(!verify_csrf())$message='Invalid request.';
 elseif(admin_role()==='data_entry' && (($pin!==''&&!empty($student['pin_hash'])) || ($nic!==''&&!empty($student['nic_hash'])) || $active!==(int)$student['is_active']))$message='Only Registrar or Super Admin can replace existing security details or change account status.';
 elseif(!valid_index_number($index)||$name===''||mb_strlen($name)>100)$message='Please enter valid data.';
 elseif($pin!==''&&!preg_match('/^\d{4,8}$/',$pin))$message='New PIN must contain 4 to 8 digits.';
 elseif($nic!==''&&!valid_nic($nic))$message='Enter a valid NIC number (old 9 digits + V/X, or new 12 digits).';
 else{
  $parts=student_id_parts($id);if(substr($index,0,2)!==$parts['section'])$message='Index section must match Student ID section.';else{
   $c=mysqli_prepare($conn,'SELECT student_id FROM students WHERE index_number=? AND student_id<>? LIMIT 1');mysqli_stmt_bind_param($c,'ss',$index,$id);mysqli_stmt_execute($c);if(mysqli_num_rows(mysqli_stmt_get_result($c))>0)$message='Index Number already exists.';else{
    $pinHash=$pin!==''?password_hash($pin,PASSWORD_DEFAULT):null;
    $nicHash=$nic!==''?password_hash($nic,PASSWORD_DEFAULT):null;
    if($pinHash!==null && $nicHash!==null){$u=mysqli_prepare($conn,'UPDATE students SET name=?,index_number=?,pin_hash=?,nic_hash=?,nic_updated_at=NOW(),is_active=? WHERE student_id=?');mysqli_stmt_bind_param($u,'ssssis',$name,$index,$pinHash,$nicHash,$active,$id);$detail='Student profile updated, PIN reset and NIC verification updated';}
    elseif($pinHash!==null){$u=mysqli_prepare($conn,'UPDATE students SET name=?,index_number=?,pin_hash=?,is_active=? WHERE student_id=?');mysqli_stmt_bind_param($u,'sssis',$name,$index,$pinHash,$active,$id);$detail='Student profile updated and PIN reset';}
    elseif($nicHash!==null){$u=mysqli_prepare($conn,'UPDATE students SET name=?,index_number=?,nic_hash=?,nic_updated_at=NOW(),is_active=? WHERE student_id=?');mysqli_stmt_bind_param($u,'sssis',$name,$index,$nicHash,$active,$id);$detail='Student profile updated and NIC verification updated';}
    else{$u=mysqli_prepare($conn,'UPDATE students SET name=?,index_number=?,is_active=? WHERE student_id=?');mysqli_stmt_bind_param($u,'ssis',$name,$index,$active,$id);$detail='Student profile updated';}
    if(mysqli_stmt_execute($u)){revoke_student_verifications($conn,$id);audit_log($conn,'UPDATE','student',$id,$detail);if($pinHash!==null)audit_log($conn,'PIN_RESET','student',$id,'PIN changed by authorized staff');if(!$active && $student['is_active'])audit_log($conn,'STUDENT_DEACTIVATED','student',$id,'Account disabled');$message='Student updated successfully.';$type='success';$student['pin_hash']=$pinHash??$student['pin_hash'];$student['name']=$name;$student['index_number']=$index;$student['is_active']=$active;if($nicHash!==null){$student['nic_hash']=$nicHash;$student['nic_updated_at']=date('Y-m-d H:i:s');}}else$message='Update failed.';
   }
  }
 }

 } catch(mysqli_sql_exception $ex) { mysqli_rollback($conn); $message='This change could not be saved. The record may be locked, protected or changed by another user. Refresh and try again.'; $type='error'; }
}
?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Student</title><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="modern-ui.css?v=20261006-modern2"></head><body><div class="main-wrapper"><?php include 'admin_nav.php'; ?><main class="content"><section class="feature-card"><h2>Edit Student</h2><form method="post" autocomplete="off"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="original_student_id" value="<?=e($id)?>"><label>Student ID</label><input type="text" value="<?=e($id)?>" disabled><label>Index Number</label><input type="text" name="index_number" required pattern="^(PS|BS)-\d{4}$" value="<?=e($student['index_number'])?>"><label>Name</label><input type="text" name="name" required maxlength="100" value="<?=e($student['name'])?>"><?php if(has_role(['super_admin','registrar'])):?><label class="checkbox-row"><input type="checkbox" name="is_active" value="1" <?=($student['is_active']??1)?'checked':''?>> Active Student Account</label><?php else:?><input type="hidden" name="is_active" value="1"><?php endif;?><div class="field-hint">Inactive students cannot sign in, but their academic records are kept.</div><?php if(has_role(['super_admin','registrar']) || empty($student['nic_hash'])):?><label>NIC Number <small>(<?=empty($student['nic_hash']??'')?'required to enable Forgot PIN':'leave blank to keep current NIC'?>)</small></label><input type="text" name="nic_number" maxlength="14" placeholder="200012345678 or 901234567V" autocomplete="off"><div class="field-hint"><?=empty($student['nic_hash']??'')?'NIC verification is not set. Enter the student NIC to enable secure PIN reset requests.':'NIC verification is already set. Enter a NIC only when it needs to be corrected or replaced.'?></div><?php endif;?><?php if(has_role(['super_admin','registrar']) || empty($student['pin_hash'])):?><label>Reset Student PIN <small>(optional)</small></label><input type="password" name="pin" inputmode="numeric" pattern="\d{4,8}" minlength="4" maxlength="8" placeholder="Leave blank to keep current PIN" autocomplete="new-password"><div class="field-hint"><?=empty($student['pin_hash'])?'PIN not set — enter a new PIN now.':'PIN is already set. Registrar / Super Admin permission is needed to reset it.'?></div><?php endif;?><div class="button-row"><a href="view_students.php" class="btn-link btn-secondary">Back</a><input type="submit" value="Save Changes"></div></form><?php if($message):?><div class="message <?=$type?>"><?=e($message)?></div><?php endif;?></section></main><?php include 'footer.php';?></div></body></html>